from core import *
rows,data=load();train=np.array([i for i,x in enumerate(rows) if x['split']=='train']);device=setup()
# An actual 20-update development profile; never an evaluation checkpoint.
dd,support=transform(data,rows,train,True,True);torch.manual_seed(901);m=model('gnn',True,support['relation_support']).to(device);opt=torch.optim.AdamW(m.parameters(),lr=.001,weight_decay=.0001);ii=train[:128];batch={k:torch.tensor(v[ii],device=device) for k,v in dd.items()};yy=torch.tensor([rows[i]['activity'] for i in ii],device=device);losses=[]
if device.startswith('cuda'):torch.cuda.synchronize()
t=time.perf_counter();cpu=time.process_time()
for _ in range(20):
 opt.zero_grad(set_to_none=True);loss=((m(**batch)-yy)**2).mean();assert torch.isfinite(loss);loss.backward();opt.step();losses.append(float(loss.detach()))
if device.startswith('cuda'):torch.cuda.synchronize()
profile=dict(optimizer_updates=20,wall_s=time.perf_counter()-t,cpu_s=time.process_time()-cpu,losses=losses,device=device,parameters=sum(p.numel() for p in m.parameters()))
atomic_torch(RUN/'profile.pt',dict(model=m.state_dict(),optimizer=opt.state_dict(),optimizer_updates=20));write(RUN/'profile.json',profile)
# Descending component size, stable hash tie-break, greedily fill the smallest outer fold.
ensi=[x for x in rows if x['dataset']=='ENsiRNA'];counts=pd.Series([x['study_group'] for x in ensi]).value_counts().to_dict();foldgroups=[[] for _ in range(5)];sizes=[0]*5
for g in sorted(counts,key=lambda g:(-counts[g],g)):
 f=min(range(5),key=lambda k:(sizes[k],k));foldgroups[f].append(g);sizes[f]+=counts[g]
folds=[];members=[]
for f,gg in enumerate(foldgroups):
 remaining=sorted(set(counts)-set(gg));inner=sorted(remaining,key=lambda g:hashlib.sha256(('inner-'+str(f)+'-'+g).encode()).hexdigest())[:2];tr=sorted(set(remaining)-set(inner));assert len(tr)>=3
 folds.append(dict(fold=f,train_groups=tr,validation_groups=inner,test_groups=gg))
 for x in ensi:members.append(dict(record_id=x['record_id'],source_family=x['source_family'],study_group=x['study_group'],sequence_group=x['sequence_group'],outer_fold=f,role='test' if x['study_group'] in gg else 'validation' if x['study_group'] in inner else 'train'))
pd.DataFrame(members).to_csv(RUN/'grouped_membership.csv',index=False)
lookup={x['record_id']:x for x in rows};pairs=readlines(OLD/'eligible_pairs.jsonl');groups=sorted({lookup[p['reference_id']]['sequence_group'] for p in pairs});assert len(groups)==12
b2folds=[]
for f in range(4):
 te=groups[f::4];remain=[g for g in groups if g not in te];va=sorted(remain,key=lambda g:hashlib.sha256(('b2-inner-'+str(f)+'-'+g).encode()).hexdigest())[:2];tr=[g for g in remain if g not in va];b2folds.append(dict(fold=f,train_groups=tr,validation_groups=va,test_groups=te))
protocol=dict(status='Retrospective targeted follow-up; APP and old internal outcomes already known',seeds=SEEDS,neural_configs=CONFIGS,tree_configs=TREE_CONFIGS,budget=dict(max_epochs=80,min_epochs=10,patience=15,batch_size=128,gradient_clip=5.,selection_seed=701,validation_tolerance=1e-8),factorial=['R0C0','R1C0','R0C1','R1C1'],controls=['chemistry_tree','token_cnn','nongraph','gnn_no_chemistry','context_ridge','mean_unweighted','mean_equal_study'],selection='Minimum equal-study validation MSE, lexical config tie-break. Two development configurations per neural/tree arm; three final seeds; no test-driven expansion.',grouped_folds=folds,outer_aggregation='Report pooled rows, equal study-linked components, equal folds. All 10 components tested exactly once; old internal test participates retrospectively.',final_deployment='For each corrected kind choose config by mean inner-validation score across five outer training populations. Fixed epoch count is rounded median of selected development epochs for that config, at least 1; train on all ENsiRNA with each of three final seeds. No APP outcomes enter selection.',b2_folds=b2folds,b2_lambdas=[0.,1.,10.],b2_neural_config=CONFIGS[0],b2_selection='For nonzero lambda choose 1 or 10 using inner equal-sequence-component pair MSE at seed701; activity-only stopping also uses inner pair MSE; final three seeds. Fixed lr .001/wd .0001 and same 80/10/15 schedule, one full training-endpoint batch per epoch. Training uses pair endpoints only, both endpoints and all related measurements grouped. No final train+validation refit.',b2_controls=['zero','training_equal_component_mean','training_majority_direction','pair_ridge_alpha1','gnn_activity','gnn_pair','nongraph_pair'],b2_weighting='Activity: equal training sequence-component mean of endpoint normalized squared errors. Pair: equal sequence-component mean of normalized squared difference errors. Both divide by training activity std squared; mean floor .05. Pair ridge alpha1 uses changed-minus-reference flattened supported node features plus guide base-position columns; intercept learns a bundle mean.',b2_dependency='Exact shared control wells/replicate covariance unresolved. Named AD1955 normalization alone does not identify shared wells. Sequence groups isolate known relationships, not certified independent assay noise. All B2 CV is exploratory conditional on one family.',external_policy='No uncertain Davis orientation repair; no scoring until primary input mapping, compatible endpoint, known-source/13mer overlap audit and development-only freeze.',resource_plan=dict(device=device,gpu_memory_fraction=.30,threads=2,maximum_fit_count=240,maximum_neural_optimizer_updates=400000,aggregate_child_cpu_limit_s=14400,aggregate_stage_wall_limit_s=14400,per_stage_timeout_s=3600,profile_seconds_per_update=profile['wall_s']/20,reason='Bounded factorial, five outer folds, three seeds, four B2 folds with a fixed two-value positive lambda grid. Stop optional testing after these comparisons. Administrative cost extra and nonzero.'))
write(RUN/'protocol.json',protocol)
write(RUN/'protocol_commit.json',dict(protocol_sha256=sha(RUN/'protocol.json'),created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),code={p.name:sha(p) for p in Path(__file__).parent.glob('*.py')}))
print('profile',profile['wall_s'],'outer sizes',sizes,'B2 groups',len(groups),flush=True)
